// === Tab: mySketch ===
let center_gravity;
let p, acc, vel;
let topspeed, dimension, c;
let num, nmax = 2000;

function setup()
{
  createCanvas(1024, 768);
  //createCanvas(windowWidth, windowHeight, WEBGL);
  colorMode(HSB);
  reset();
  background(0);
	window.simulatedMouseX = width / 2;
	window.simulatedMouseY = height / 2;
}

function reset()
{
  num = 400;
  topspeed = 20;
  center_gravity = new PVector(width/2, height/2);
  p = new Array(nmax);
  acc = new Array(nmax);
  vel = new Array(nmax);
  for (i=0; i<num; i++)
  {
    p[i] = new PVector(random(width), random(height));
    acc[i] = new PVector(0, 0);
    vel[i] = new PVector(0, 0);
  }
}

function draw()
{
  background(51);
  center_gravity.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  center_gravity.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
  move();
  show();
  c += 0.5;
}

function move()
{
  for (i=0; i<num; i++)
  {
    acc[i].x = center_gravity.x - p[i].x; 
    acc[i].y = center_gravity.y - p[i].y;
    acc[i].normalize();
    acc[i].mult(0.65);
    vel[i].add(acc[i]);
    vel[i].limit(topspeed);
    p[i].add(vel[i]);
  }
}

function show()
{
  for (i=0; i<num-1; i++)
  {
    fill(c%255, 200, 255);
    stroke(c%255, 200, 255);
    ellipse(p[i].x, p[i].y, 4, 4);
  }
}

